window.DATA={"age_salary.csv": "Age,Salary\n22,350000\n35,850000\n45,1200000\n", "customers.csv": "Age,AnnualIncome,SpendingScore\n19,15000,39\n21,15000,81\n23,16000,6\n31,17000,77\n35,20000,35\n40,25000,42\n45,30000,54\n50,40000,42\n22,35000,72\n28,45000,65\n", "housing.csv": "MedInc,AveRooms,HouseAge,MedHouseVal\n8.3252,6.98,41,4.526\n8.3014,6.24,21,3.585\n5.6431,8.29,52,3.521\n3.8462,5.18,52,3.413\n4.0368,6.27,52,3.422\n3.6591,4.96,52,2.697\n3.1200,4.80,52,2.992\n2.0804,4.29,42,2.411\n3.6912,4.97,50,2.267\n3.2031,5.48,52,2.611\n"};
window.HARNESS_PY="# harness.py - runs one student snippet and returns its text output + any plots.\n# The SAME file is used inside the browser (Pyodide) and on the box (real Python) so outputs can be compared.\nimport sys, io, os, types, base64, linecache, traceback, warnings, contextlib\n\nDATA_DIR = os.getcwd()  # the folder that holds books_page1.html, the CSV files, etc.\n\n\ndef _install_requests_stand_in():\n    \"\"\"Browsers block live requests (CORS), so `requests.get` here returns a SAVED copy of books.toscrape.com.\"\"\"\n    class Response:  # only the three things the exam code uses: status_code, text, content\n        def __init__(self, status, text):\n            self.status_code = status\n            self.text = text\n            self.content = text.encode(\"utf-8\")\n\n    def get(url, *args, **kwargs):\n        if \"books.toscrape.com\" in str(url):  # only this practice site is saved offline\n            with open(os.path.join(DATA_DIR, \"books_page1.html\"), encoding=\"utf-8\") as f:\n                return Response(200, f.read())\n        return Response(404, \"Not available offline: only books.toscrape.com is saved on this site\")\n\n    mod = types.ModuleType(\"requests\")\n    mod.get = get\n    mod.__doc__ = \"offline stand-in for requests (practice site only)\"\n    sys.modules[\"requests\"] = mod\n\n\ndef _axmeta(ax):\n    \"\"\"Describe one Axes (title, labels, legend, grid, bars, lines, points) so hidden tests can check a chart.\"\"\"\n    def grid_on(axis):\n        try:\n            return any(l.get_visible() for l in axis.get_gridlines())\n        except Exception:\n            return False\n    bars = []\n    for c in ax.containers:  # bar / barh make BarContainers\n        try:\n            vals = [float(v) for v in c.datavalues]\n        except Exception:\n            vals = []\n        bars.append({\"orientation\": getattr(c, \"orientation\", \"vertical\"), \"values\": vals, \"n\": len(c.patches),\n                     \"colors\": [list(p.get_facecolor()) for p in c.patches], \"label\": c.get_label()})\n    lines = [{\"x\": [float(v) for v in l.get_xdata()], \"y\": [float(v) for v in l.get_ydata()], \"label\": l.get_label(),\n              \"marker\": l.get_marker(), \"color\": l.get_color()} for l in ax.lines]\n    points = []\n    for col in ax.collections:  # scatter makes a PathCollection with offsets\n        try:\n            offs = col.get_offsets()\n            if len(offs):\n                points.append({\"n\": int(len(offs)), \"x\": [float(v) for v in offs[:, 0]], \"y\": [float(v) for v in offs[:, 1]],\n                               \"label\": col.get_label()})\n        except Exception:\n            pass\n    leg = ax.get_legend()\n    return {\"title\": ax.get_title(), \"xlabel\": ax.get_xlabel(), \"ylabel\": ax.get_ylabel(), \"legend\": leg is not None,\n            \"legend_labels\": [t.get_text() for t in leg.get_texts()] if leg else [],\n            \"grid\": grid_on(ax.xaxis) or grid_on(ax.yaxis), \"bars\": bars, \"lines\": lines, \"points\": points,\n            \"xticklabels\": [t.get_text() for t in ax.get_xticklabels()], \"yticklabels\": [t.get_text() for t in ax.get_yticklabels()]}\n\n\ndef _exec(code, name=\"<your code>\"):\n    \"\"\"Run `code` in a fresh namespace. Returns (result dict, namespace, figure metadata list).\"\"\"\n    warnings.simplefilter(\"ignore\")  # keep the output clean: only what the student's code prints\n    _install_requests_stand_in()\n    out, images, error, figs = io.StringIO(), [], None, []\n    plt = None\n    if \"matplotlib\" in code:  # only touch matplotlib when the snippet needs it\n        import matplotlib\n        matplotlib.use(\"Agg\")  # draw to memory (no window)\n        import matplotlib.pyplot as plt\n        plt.close(\"all\")\n\n        def _grab():  # turn every open figure into a PNG, then close it\n            for num in plt.get_fignums():\n                fg = plt.figure(num)\n                figs.append({\"axes\": [_axmeta(a) for a in fg.axes], \"size\": [float(v) for v in fg.get_size_inches()]})\n                buf = io.BytesIO()\n                plt.figure(num).savefig(buf, format=\"png\", dpi=100, bbox_inches=\"tight\")\n                images.append(base64.b64encode(buf.getvalue()).decode())\n            plt.close(\"all\")\n\n        plt.show = lambda *a, **k: _grab()  # plt.show() now captures the plot instead of opening a window\n    linecache.cache[name] = (len(code), None, code.splitlines(True), name)  # lets tracebacks show your lines\n    ns = {\"__name__\": \"__main__\"}\n    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(out):\n        try:\n            exec(compile(code, name, \"exec\"), ns)\n        except BaseException as e:  # noqa: BLE001 - show every error the way Python would\n            error = _format(e, name)\n    if plt is not None:\n        try:\n            _grab()  # a figure the code never showed\n        except Exception:\n            pass\n    return {\"out\": out.getvalue(), \"error\": error, \"images\": images}, ns, figs\n\n\ndef run(code, name=\"<your code>\"):\n    \"\"\"Run `code`. Returns dict(out=str, error=str|None, images=[base64 png, ...]).\"\"\"\n    return _exec(code, name)[0]\n\n\ndef grade(code, tests, name=\"<your code>\"):\n    \"\"\"Run the student's code, then check each hidden test (an expression) on its own.\n    tests = [[todo_number, label, expression], ...]. Returns the run result plus a pass/fail list.\"\"\"\n    res, ns, figs = _exec(code, name)\n    env = dict(ns)  # the student's variables are visible to the tests\n    env.update({\"NS\": ns, \"_out\": res[\"out\"], \"_src\": code, \"_err\": res[\"error\"], \"_figs\": figs, \"_ax\": (figs[-1][\"axes\"][0] if figs and figs[-1][\"axes\"] else None)})\n    import re, numpy, pandas  # the tests may use np / pd even when the student forgot the import\n    env.setdefault(\"np\", numpy); env.setdefault(\"pd\", pandas)\n    env[\"near\"] = lambda a, b, t=0.011: abs(float(a) - float(b)) <= t  # numbers equal within a small tolerance\n    env[\"printed\"] = lambda *subs: all(str(s) in res[\"out\"] for s in subs)  # every piece appears in the output\n    nocomment = \"\\n\".join(re.sub(r\"#.*\", \"\", l) for l in code.split(\"\\n\"))  # the code without its comments\n    env[\"uses\"] = lambda pattern: re.search(pattern, nocomment) is not None  # the code (not comments) contains this pattern\n    env[\"col\"] = lambda n: ns.get(n)  # safe lookup of a student variable\n\n    def ref(csv, xcol, ycol):  # the reference regression (80/20 split, random_state=42) for comparing answers\n        from sklearn.model_selection import train_test_split\n        from sklearn.linear_model import LinearRegression\n        from sklearn.metrics import mean_squared_error\n        d = pandas.read_csv(csv)\n        xt, xs, yt, ys = train_test_split(d[[xcol]], d[ycol], test_size=0.2, random_state=42)\n        m = LinearRegression().fit(xt, yt)\n        p = m.predict(xs)\n        return {\"slope\": float(m.coef_[0]), \"intercept\": float(m.intercept_), \"mse\": float(mean_squared_error(ys, p)), \"pred\": [float(v) for v in p],\n                \"n_train\": len(xt), \"n_test\": len(xs), \"actual\": [float(v) for v in ys]}\n    env[\"ref\"] = ref\n    checks = []\n    for todo, label, expr in tests:\n        try:\n            ok = bool(eval(expr, env))  # noqa: S307 - our own hidden test, not student input\n        except Exception:\n            ok = False\n        checks.append({\"todo\": todo, \"label\": label, \"ok\": ok})\n    res[\"checks\"] = checks\n    return res\n\n\ndef _format(e, name):\n    if isinstance(e, SyntaxError):  # compile-time errors have no useful traceback\n        return \"\".join(traceback.format_exception_only(type(e), e)).rstrip()\n    frames = [f for f in traceback.extract_tb(e.__traceback__) if f.filename == name]\n    lines = [\"Traceback (most recent call last):\"]\n    for f in frames:\n        lines.append(f'  File \"{name}\", line {f.lineno}, in {f.name}')\n        if f.line:\n            lines.append(\"    \" + f.line.strip())\n    lines.append(\"\".join(traceback.format_exception_only(type(e), e)).rstrip())\n    return \"\\n\".join(lines)\n";
